1	#!/usr/bin/env node
2	/** Simulation-only inverted-pendulum experiments and automatic reports. */
3	
4	import {isAbsolute,resolve as presolve} from 'node:path';
5	import {randomUUID,createHash} from 'node:crypto';
6	import {readFileSync} from 'node:fs';
7	import {performance} from 'node:perf_hooks';
8	
9	import {parseGainList,SIM_DEFAULTS,TUNABLE} from './lib/protocol.js';
10	import { computeMetrics } from './lib/metrics.js';
11	import { diagnose } from './lib/diagnostics.js';
12	import { loadConfig, costWeights } from './lib/config.js';
13	import { writeRunCsv, appendIndex, readIndex, paths } from './lib/store.js';
14	import { runSim, SIM_PRESETS, SIM_MODEL_VERSION } from './backends/sim.js';
15	import { runReplay } from './backends/replay.js';
16	import {normalizeSimProfile,simConditions} from './lib/sim-options.js';
17	import {normalizeSimController} from './lib/sim-controller.js';
18	import {writeTrialArtifacts,writeCampaignReport} from './lib/reports.js';
19	
20	const argv = process.argv.slice(2);
21	const cmd = argv[0];
22	const rest = argv.slice(1);
23	const flagErrors = [];
24	const flags = parseFlags(rest);
25	const positional = rest.filter((a) => !a.startsWith('--'));
26	
27	function parseFlags(list) {
28	  const f = {};
29	  for (let i = 0; i < list.length; i++) {
30	    const a = list[i];
31	    if (!a.startsWith('--')) { if (cmd === 'trial') flagErrors.push(`多余的位置参数: ${a}`); continue; }
32	    const key = a.slice(2);
33	    if (Object.hasOwn(f, key)) flagErrors.push(`重复选项: --${key}`);
34	    const next = list[i + 1];
35	    if (['json','help'].includes(key)) { f[key] = true; continue; }
36	    if (next === undefined || next.startsWith('--')) { f[key] = true; }
37	    else { f[key] = next; i++; }
38	  }
39	  return f;
40	}
41	
42	const emit = (obj, human) => {
43	  if (flags.json) console.log(JSON.stringify(obj, null, 2));
44	  else console.log(human ?? JSON.stringify(obj, null, 2));
45	};
46	
47	async function main() {
48	  if (flagErrors.length) throw new Error(flagErrors.join('; '));
49	  if (!cmd || flags.help) return usage();
50	
51	  switch (cmd) {
52	    case 'params': return cmdParams();
53	    case 'trial': return cmdTrial();
54	    case 'selftest': return cmdSelftest();
55	    case 'runs': return cmdRuns();
56	    case 'report': return cmdReport();
57	    default: throw Error('未知命令；本项目仅支持仿真、回放和报告');
58	  }
59	}
60	
61	function usage(){console.log('PID AI 仿真助手\n命令: params | selftest | trial --backend sim --gains "Kp=4,Ki=0,Kd=8" --json | report --campaign ID --json | runs\ntrial自动生成CSV、JSON、响应/控制/相图SVG及HTML；不包含设备后端。');}
62	function cmdParams(){const {config,source}=loadConfig();emit({mode:'simulation-only',model:'nonlinear second-order single pendulum',defaults:SIM_DEFAULTS,tunable:TUNABLE,config,configSource:source});}
63	function cmdReport(){for(const k of Object.keys(flags))if(!['campaign','out','json'].includes(k))throw Error('未知report选项: '+k);emit(writeCampaignReport({campaign:flags.campaign,outDir:flags.out}));}
64	async function cmdTrial() {
65	  const { config: cfg, source: cfgSource } = loadConfig();
66	  const backend = flags.backend ?? 'sim';
67	  if(!['sim','replay'].includes(backend))throw Error('仅支持sim/replay；设备后端已移除');
68	  const durationMs = Number(flags.dur ?? cfg.trial.durationMs);
69	  const target = Number(flags.target ?? 0);
70	  if (!Number.isFinite(durationMs) || durationMs < 1000 || durationMs > 60000)
71	    throw new Error('trial 时长必须是 1000–60000ms 的有限数字');
72	  if (!Number.isFinite(target)) throw new Error('target 必须是有限数字');
73	  const allowed = ['backend','dur','target','gains','json','x0','seed','disturb','csv',
74	    'fallLimit','tag','campaign','reason','parent','purpose','plan','sim-profile','sim-controller'];
75	  for (const key of Object.keys(flags)) if (!allowed.includes(key)) throw new Error(`未知 trial 选项: --${key}`);
76	  for (const key of ['backend','dur','target','gains','x0','seed','disturb','csv','fallLimit','tag','campaign','reason','parent','purpose','plan','sim-profile','sim-controller'])
77	    if (flags[key] === true) throw new Error(`--${key} 缺少值`);
78	  if (flags.tag && !/^[a-zA-Z0-9_-]{1,80}$/.test(flags.tag)) throw new Error('非法 tag');
79	  if (flags.campaign && !/^[a-zA-Z0-9_-]{1,80}$/.test(flags.campaign)) throw new Error('非法 campaign');
80	  if(backend!=='sim' && (flags.campaign || flags.plan)) throw Error('campaign/plan本轮仅允许sim，不污染其他后端记录');
